  "prediction_basis_card_ids": ["C22", "C01", "C07", "C53", "C02", "C79", "C96", "C56", "C102"],
  "claims": [
    {
      "claim": "Direct absolute oral bioavailability measurements for tetrabenazine (0.1–8.5%), meptazinol (~9%), 2-methoxyestradiol (1–3%), and apocynin (2.8–8.3%) are all below 20%; the query shares their methoxyaryl ketone/enol ether and phenol motifs.",
      "card_ids": ["C22", "C01", "C07", "C37", "C53", "C56", "C02", "C79", "C96"]
    },
    {
      "claim": "L3 oral AUC/Cmax records for oxycodone, hydrocodone, and morphine show substantial exposure, but these morphinans lack the query's guaiacol and enol ether substitution and no F value is reported; they do not affirmatively establish F >= 20% for the query.",
      "card_ids": ["C154", "C125", "C145", "C151", "C127"]
    },
    {
      "claim": "L3 low-exposure records for naloxone and naltrexone (Cmax 0.07–584 pg/mL) are consistent with low oral F for some morphinans, but their different N-substituents and lack of methoxy/enol ether limit transfer to the query.",
      "card_ids": ["C137", "C143", "C112", "C135"]
    },
    {
      "claim": "The only L3 oral-vs-IV ratio (DHE MAP0004, ~39%) is for an ergot alkaloid with a specialized formulation and is not transferable to the query.",
      "card_ids": ["C114", "C131"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C154", "C125", "C145", "C151", "C127", "C137", "C143", "C114"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the query molecule.",
    "L3 records report AUC/Cmax without matched IV comparators for most morphinans, so F cannot be derived from them.",
    "No L3 record matches the query's guaiacol (OMe+OH) and enol ether substitution pattern.",
    "Conflicting morphinan class behavior (oxycodone high exposure vs naloxone low exposure) is unresolved for the query.",
    "The specific first-pass liability of the enol ether/ketone and phenol motifs is not directly quantified."
  ],
  "decision_summary": "L3 adds oral exposure data for morphinan opioids, some with high exposure, but none match the query's guaiacol/enol ether substitution and none report F. Direct low-F measurements for tetrabenazine, meptazinol, 2-methoxyestradiol, and apocynin remain the most threshold-relevant transferable evidence. Prediction remains low, with reduced confidence due to conflicting morphinan exposure data."
}

